from pysat.solvers import Glucose3
from pysat.card import *

# Variables:
# For each vertex v (0..17) and label l (0..33): x_v_l = 1 if vertex v gets label l
# For each edge e (0..32) and diff d (1..33): y_e_d = 1 if edge e has diff d

n_vertices = 18
n_labels = 34
n_edges = 33
n_diffs = 33

# Build edge list
edges = []
for g in range(6):
    edges.append((g*3+0, g*3+1))
    edges.append((g*3+1, g*3+2))
    edges.append((g*3+0, g*3+2))
for g in range(5):
    for i in range(3):
        edges.append((g*3+i, (g+1)*3+i))

print(f"Edges: {edges}")

# Variable encoding:
# x[v][l] = vertex v has label l: var = v * 34 + l + 1 (1-indexed for SAT)
# y[e][d] = edge e has diff d: var = 18*34 + e*33 + d + 1

def x_var(v, l):
    return v * 34 + l + 1

def y_var(e, d):
    return 18 * 34 + e * 33 + d + 1

max_var = 18 * 34 + 33 * 33
print(f"Max variable: {max_var}")

solver = Glucose3()

# Each vertex gets exactly one label
for v in range(n_vertices):
    # At least one
    solver.add_clause([x_var(v, l) for l in range(n_labels)])
    # At most one
    for l1 in range(n_labels):
        for l2 in range(l1+1, n_labels):
            solver.add_clause([-x_var(v, l1), -x_var(v, l2)])

# Each label used at most once
for l in range(n_labels):
    for v1 in range(n_vertices):
        for v2 in range(v1+1, n_vertices):
            solver.add_clause([-x_var(v1, l), -x_var(v2, l)])

# Each edge gets exactly one diff
for e in range(n_edges):
    solver.add_clause([y_var(e, d) for d in range(1, n_diffs+1)])
    for d1 in range(1, n_diffs+1):
        for d2 in range(d1+1, n_diffs+1):
            solver.add_clause([-y_var(e, d1), -y_var(e, d2)])

# Each diff used at most once
for d in range(1, n_diffs+1):
    for e1 in range(n_edges):
        for e2 in range(e1+1, n_edges):
            solver.add_clause([-y_var(e1, d), -y_var(e2, d)])

# Link vertex labels to edge diffs
for e, (u, v) in enumerate(edges):
    for l_u in range(n_labels):
        for l_v in range(n_labels):
            if l_u == l_v:
                continue
            d = abs(l_u - l_v)
            if d < 1 or d > n_diffs:
                continue
            # If x[u][l_u] and x[v][l_v], then y[e][d]
            # Equivalent to: -x[u][l_u] or -x[v][l_v] or y[e][d]
            solver.add_clause([-x_var(u, l_u), -x_var(v, l_v), y_var(e, d)])

print("Clauses added, solving...")
if solver.solve():
    model = solver.get_model()
    print("SAT!")

    # Extract solution
    solution = [0] * n_vertices
    for v in range(n_vertices):
        for l in range(n_labels):
            if x_var(v, l) in model:
                solution[v] = l
                break

    print(f"Solution: {solution}")

    # Verify
    diffs = []
    for u, v in edges:
        diffs.append(abs(solution[u] - solution[v]))
    print(f"Unique diffs: {len(set(diffs))}")
    print(f"Sorted: {sorted(diffs)}")
else:
    print("UNSAT")
